<?php
namespace LaraSelector\Http;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use LaraSelector\Activation; use LaraSelector\LaraSelectorToken; use LaraSelector\PhpSourceNavigator;
final class LaraSelectorController extends Controller {
public function capabilities(Request $r){$this->gate();return response()->json(['protocol'=>2,'capabilities'=>['resolve','editor-uri','page-controller','form-action']]);}
public function handshake(Request $r){$this->gate();if(!$this->sameOrigin($r))return $this->error('origin_denied',403);$t=bin2hex(random_bytes(24));session(['laraselector_token'=>$t]);return response()->json(['ok'=>true])->header('X-LaraSelector-Token',$t);}
public function resolve(Request $r,LaraSelectorToken $tokens,PhpSourceNavigator $php){$this->gate();if(!$this->sameOrigin($r)||!hash_equals((string)session('laraselector_token'),(string)$r->header('X-LaraSelector-Token')))return $this->error('access_denied',403);try{$blade=$tokens->resolve((string)$r->input('id'));}catch(\InvalidArgumentException $e){return $this->error('invalid_source',422,$e->getMessage());}$targets=['blade'=>$this->target($blade)];if($page=$php->page($r,(string)$r->input('page'))) $targets['pageController']=$this->target($page);$form=$r->input('form');if(is_array($form)&&($action=$php->form($r,$form)))$targets['formAction']=$this->target($action);return response()->json(['source'=>$targets['blade']['source'],'editorUri'=>$targets['blade']['editorUri'],'targets'=>$targets]);}
private function target(array $s):array{return['source'=>['path'=>$s['relative'],'line'=>$s['line']],'editorUri'=>$this->editorUri($s['path'],$s['line'])];}
private function editorUri(string $p,int $line):string{foreach((array)config('laraselector.path_mapping',[])as$f=>$t)if(str_starts_with($p,$f)){$p=$t.substr($p,strlen($f));break;}$e=(string)config('laraselector.editor','vscode');if(!in_array($e,['vscode','cursor','phpstorm'],true))$e='vscode';return $e==='phpstorm'?'phpstorm://open?file='.rawurlencode($p).'&line='.$line:$e.'://file/'.str_replace('%2F','/',rawurlencode($p)).':'.$line.':1';}
private function gate():void{if(!app(Activation::class)->active())abort(404);}
private function sameOrigin(Request $r):bool{$o=$r->header('Origin');return$o===null||$o===$r->getSchemeAndHttpHost();}private function error(string$c,int$s,?string$d=null){return response()->json(['error'=>['code'=>$c,'message'=>$d?:$c]],$s);}}
